 // ============================================================
// FINANCEFLOW - ADAPTADOR PLUGGY -> PADRÃO CONCILIAÇÃO EXTRATO
// n8n Code Node
// ============================================================

// Aceita:
// 1) vários items do n8n
// 2) um item contendo um array
// 3) json.movimentos / json.transactions / json.results
const entradas = $input.all();

let dados = [];

for (const entrada of entradas) {
  const j = entrada.json;

  if (Array.isArray(j)) {
    dados.push(...j);
  } else if (Array.isArray(j.movimentos)) {
    dados.push(...j.movimentos);
  } else if (Array.isArray(j.transactions)) {
    dados.push(...j.transactions);
  } else if (Array.isArray(j.results)) {
    dados.push(...j.results);
  } else if (j && j.id) {
    dados.push(j);
  }
}

// ============================================================
// AUXILIARES
// ============================================================

function arredondar(valor) {
  return Math.round((Number(valor) + Number.EPSILON) * 100) / 100;
}

function dataISO(valor) {
  if (!valor) return null;

  // evita problema de timezone:
  // "2026-08-20T03:00:00.000Z" -> "2026-08-20"
  return String(valor).substring(0, 10);
}

function obterDocumento(item) {
  return (
    item.paymentData?.referenceNumber ??
    item.paymentData?.authenticationCode ??
    item.providerCode ??
    item.providerId ??
    null
  );
}

function obterHistorico(item) {
  return (
    item.description ??
    item.descriptionRaw ??
    item.merchant?.businessName ??
    'MOVIMENTO BANCARIO'
  );
}

// ============================================================
// TRANSFORMA MOVIMENTOS
// ============================================================

const movimentos = dados
  .filter(item => item && item.status !== 'PENDING')
  .map(item => {
    const valorOriginal = Number(item.amount ?? 0);

    let tipo;

    if (item.type === 'CREDIT') {
      tipo = 'C';
    } else if (item.type === 'DEBIT') {
      tipo = 'D';
    } else {
      tipo = valorOriginal >= 0 ? 'C' : 'D';
    }

    return {
      data: dataISO(item.date),

      historico: obterHistorico(item),

      documento: obterDocumento(item),

      valor: arredondar(Math.abs(valorOriginal)),

      tipo,

      saldo:
        item.balance !== null &&
        item.balance !== undefined
          ? arredondar(item.balance)
          : null,

      natureza_financeira: null,

      // ----------------------------------------------------
      // DADOS EXTRAS PLUGGY
      // Não atrapalham sua estrutura e podem ser úteis depois
      // ----------------------------------------------------
      id_externo: item.id ?? null,
      categoria: item.category ?? null,
      categoria_id: item.categoryId ?? null,
      status: item.status ?? null,
      conta_externa_id: item.accountId ?? null,

      forma_pagamento:
        item.paymentData?.paymentMethod ?? null,

      contraparte:
        item.paymentData?.receiver?.name ??
        item.paymentData?.payer?.name ??
        item.merchant?.businessName ??
        null,

      documento_contraparte:
        item.paymentData?.receiver?.documentNumber?.value ??
        item.paymentData?.payer?.documentNumber?.value ??
        item.merchant?.cnpj ??
        null
    };
  });

// ============================================================
// ORDENA DO MAIS ANTIGO PARA O MAIS NOVO
// ============================================================

movimentos.sort((a, b) => {
  if (!a.data) return 1;
  if (!b.data) return -1;

  return a.data.localeCompare(b.data);
});

// ============================================================
// TOTAIS
// ============================================================

const creditos = movimentos.filter(m => m.tipo === 'C');
const debitos = movimentos.filter(m => m.tipo === 'D');

const totalCreditos = arredondar(
  creditos.reduce((acc, m) => acc + Number(m.valor || 0), 0)
);

const totalDebitos = arredondar(
  debitos.reduce((acc, m) => acc + Number(m.valor || 0), 0)
);

// ============================================================
// SALDOS
//
// Pluggy neste retorno está trazendo balance = null.
// Portanto só calculamos saldo quando existir balance.
// ============================================================

const movimentosComSaldo = movimentos.filter(
  m => m.saldo !== null && m.saldo !== undefined
);

let saldoInicial = null;
let saldoFinal = null;
let saldoCalculado = null;
let diferencaSaldo = null;
let saldoConfere = null;

if (movimentosComSaldo.length > 0) {

  const primeiroComSaldo = movimentosComSaldo[0];
  const ultimoComSaldo =
    movimentosComSaldo[movimentosComSaldo.length - 1];

  // Descobre saldo antes do primeiro movimento
  if (primeiroComSaldo.tipo === 'C') {
    saldoInicial = arredondar(
      primeiroComSaldo.saldo - primeiroComSaldo.valor
    );
  } else {
    saldoInicial = arredondar(
      primeiroComSaldo.saldo + primeiroComSaldo.valor
    );
  }

  saldoFinal = arredondar(ultimoComSaldo.saldo);

  saldoCalculado = arredondar(
    saldoInicial + totalCreditos - totalDebitos
  );

  diferencaSaldo = arredondar(
    saldoCalculado - saldoFinal
  );

  saldoConfere = Math.abs(diferencaSaldo) <= 0.01;
}

// ============================================================
// DIAGNÓSTICO
// ============================================================

const diagnostico = {

  tipo_layout: 'PLUGGY_API',

  quantidade_linhas: dados.length,

  registros: movimentos.length,

  creditos: creditos.length,

  debitos: debitos.length,

  total_creditos: totalCreditos,

  total_debitos: totalDebitos,

  saldo_inicial: saldoInicial,

  saldo_final: saldoFinal,

  saldo_calculado: saldoCalculado,

  diferenca_saldo: diferencaSaldo,

  saldo_confere: saldoConfere,

  primeiro_movimento:
    movimentos.length > 0
      ? {
          data: movimentos[0].data,
          historico: movimentos[0].historico,
          documento: movimentos[0].documento,
          valor: movimentos[0].valor,
          tipo: movimentos[0].tipo,
          saldo: movimentos[0].saldo,
          natureza_financeira:
            movimentos[0].natureza_financeira
        }
      : null,

  ultimo_movimento:
    movimentos.length > 0
      ? {
          data: movimentos[movimentos.length - 1].data,
          historico: movimentos[movimentos.length - 1].historico,
          documento:
            movimentos[movimentos.length - 1].documento,
          valor:
            movimentos[movimentos.length - 1].valor,
          tipo:
            movimentos[movimentos.length - 1].tipo,
          saldo:
            movimentos[movimentos.length - 1].saldo,
          natureza_financeira:
            movimentos[movimentos.length - 1]
              .natureza_financeira
        }
      : null
};

// ============================================================
// RETORNO PADRÃO FINANCEFLOW
// ============================================================

return [
  {
    json: {
      ok: true,

      banco: 'PLUGGY',

      quantidade: movimentos.length,

      movimentos,

      diagnostico
    }
  }
];

 const entradasMerge = $input.all().map(item => item.json);

// Localiza conta e extrato dentro do Merge
const conta = entradasMerge.find(item =>
  item?.id &&
  item?.type === "BANK" &&
  item?.bankData
);

const extrato = entradasMerge.find(item =>
  Array.isArray(item?.results)
);

if (!conta) {
  throw new Error("Dados da conta/saldo não encontrados no Merge.");
}

if (!extrato) {
  throw new Error("Extrato não encontrado no Merge.");
}

// Mantém somente movimentos confirmados.
// PENDING será completamente descartado.
const movimentosConfirmados = extrato.results.filter(
  movimento => movimento.status === "POSTED"
);

const totalEntradas = movimentosConfirmados
  .filter(movimento => Number(movimento.amount) > 0)
  .reduce(
    (total, movimento) => total + Number(movimento.amount),
    0
  );

const totalSaidas = Math.abs(
  movimentosConfirmados
    .filter(movimento => Number(movimento.amount) < 0)
    .reduce(
      (total, movimento) => total + Number(movimento.amount),
      0
    )
);

const movimentacaoLiquida =
  totalEntradas - totalSaidas;

const saldoFinal = Number(
  conta.bankData?.closingBalance ??
  conta.balance ??
  0
);

const saldoAnterior =
  saldoFinal - movimentacaoLiquida;

const transferNumber =
  conta.bankData?.transferNumber ?? "";

const partesConta = transferNumber.split("/");

const codigoBanco = partesConta[0] ?? null;
const agencia = partesConta[1] ?? null;

const numeroConta =
  partesConta.slice(2).join("/") ||
  conta.number ||
  null;

const arredondar = valor =>
  Math.round(
    (Number(valor) + Number.EPSILON) * 100
  ) / 100;

// Ordena do movimento mais antigo para o mais recente
const movimentosOrdenados = [...movimentosConfirmados].sort(
  (a, b) => new Date(a.date) - new Date(b.date)
);

// Calcula o saldo depois de cada movimento
let saldoAcumulado = saldoAnterior;

const movimentos = movimentosOrdenados.map(movimento => {
  saldoAcumulado += Number(movimento.amount);

  return {
    id: movimento.id,
    data: movimento.date,
    descricao: movimento.description,
    descricao_original: movimento.descriptionRaw,
    tipo: movimento.type,
    valor: Number(movimento.amount),
    saldo: arredondar(saldoAcumulado),
    categoria: movimento.category,
    categoria_id: movimento.categoryId,
    status: movimento.status,
    operacao: movimento.operationType,
    provider_id: movimento.providerId,
    account_id: movimento.accountId
  };
});

return [
  {
    json: {
      ok: true,

      conta: {
        banco: conta.name,
        codigo_banco: codigoBanco,
        agencia,
        numero: numeroConta,
        titular: conta.owner,
        documento: conta.taxNumber,
        moeda: conta.currencyCode,
        tipo: conta.type,
        subtipo: conta.subtype
      },

      pluggy: {
        item_id: conta.itemId,
        account_id: conta.id,
        atualizado_em: conta.updatedAt
      },

      resumo: {
        saldo_anterior: arredondar(saldoAnterior),
        total_entradas: arredondar(totalEntradas),
        total_saidas: arredondar(totalSaidas),
        movimentacao_liquida: arredondar(
          movimentacaoLiquida
        ),
        saldo_final: arredondar(saldoFinal),
        quantidade: movimentos.length
      },

      movimentos,

      paginacao: {
        next: extrato.next ?? null
      }
    }
  }
];

 const entradasMerge = $input.all().map(item => item.json);

// Localiza a resposta do endpoint /accounts
const respostaContas = entradasMerge.find(item =>
  Array.isArray(item?.results) &&
  item.results.some(registro =>
    registro?.type === "BANK" &&
    registro?.bankData
  )
);

// Localiza a resposta do endpoint /v2/transactions
const extrato = entradasMerge.find(item =>
  Array.isArray(item?.results) &&
  item.results.some(registro =>
    registro?.date &&
    registro?.amount !== undefined
  )
);

if (!respostaContas) {
  throw new Error(
    "Resposta das contas bancárias não encontrada no Merge."
  );
}

if (!extrato) {
  throw new Error(
    "Resposta das transações não encontrada no Merge."
  );
}

// Seleciona somente a conta corrente
const conta = respostaContas.results.find(registro =>
  registro?.type === "BANK" &&
  registro?.subtype === "CHECKING_ACCOUNT" &&
  registro?.bankData
);

if (!conta) {
  throw new Error(
    "Conta CHECKING_ACCOUNT não encontrada."
  );
}

// Elimina movimentos pendentes
const movimentosConfirmados = extrato.results.filter(
  movimento =>
    movimento?.status === "POSTED" &&
    movimento?.amount !== undefined
);

const totalEntradas = movimentosConfirmados
  .filter(movimento => Number(movimento.amount) > 0)
  .reduce(
    (total, movimento) =>
      total + Number(movimento.amount),
    0
  );

const totalSaidas = Math.abs(
  movimentosConfirmados
    .filter(movimento => Number(movimento.amount) < 0)
    .reduce(
      (total, movimento) =>
        total + Number(movimento.amount),
      0
    )
);

const movimentacaoLiquida =
  totalEntradas - totalSaidas;

const saldoFinal = Number(
  conta.bankData?.closingBalance ??
  conta.balance ??
  0
);

const saldoAnterior =
  saldoFinal - movimentacaoLiquida;

const transferNumber =
  conta.bankData?.transferNumber ?? "";

const partesConta =
  transferNumber.split("/");

const codigoBanco =
  partesConta[0] || null;

const agencia =
  partesConta[1] || null;

const numeroConta =
  partesConta.slice(2).join("/") ||
  conta.number ||
  null;

const arredondar = valor =>
  Math.round(
    (Number(valor) + Number.EPSILON) * 100
  ) / 100;

// Coloca os movimentos do mais antigo para o mais recente
const movimentosOrdenados =
  [...movimentosConfirmados].sort(
    (a, b) =>
      new Date(a.date) - new Date(b.date)
  );

let saldoAcumulado = saldoAnterior;

const movimentos = movimentosOrdenados.map(
  movimento => {
    const valor =
      Number(movimento.amount);

    saldoAcumulado += valor;

    return {
      id: movimento.id,

      data: movimento.date,

      descricao:
        movimento.description ||
        movimento.descriptionRaw ||
        "Movimento bancário",

      descricao_original:
        movimento.descriptionRaw ||
        movimento.description ||
        null,

      tipo:
        movimento.type,

      valor,

      saldo:
        arredondar(saldoAcumulado),

      categoria:
        movimento.category ?? null,

      categoria_id:
        movimento.categoryId ?? null,

      status:
        movimento.status,

      operacao:
        movimento.operationType ?? null,

      provider_id:
        movimento.providerId ?? null,

      account_id:
        movimento.accountId ??
        conta.id
    };
  }
);

// O Code do n8n precisa obrigatoriamente retornar
// um array contendo objetos com a propriedade json.
return [
  {
    json: {
      ok: true,

      conta: {
        banco: conta.name,
        codigo_banco: codigoBanco,
        agencia,
        numero: numeroConta,
        titular: conta.owner,
        documento: conta.taxNumber,
        moeda: conta.currencyCode,
        tipo: conta.type,
        subtipo: conta.subtype
      },

      pluggy: {
        item_id: conta.itemId,
        account_id: conta.id,
        atualizado_em: conta.updatedAt
      },

      resumo: {
        saldo_anterior:
          arredondar(saldoAnterior),

        total_entradas:
          arredondar(totalEntradas),

        total_saidas:
          arredondar(totalSaidas),

        movimentacao_liquida:
          arredondar(movimentacaoLiquida),

        saldo_final:
          arredondar(saldoFinal),

        quantidade:
          movimentos.length
      },

      movimentos,

      paginacao: {
        next:
          extrato.next ?? null
      }
    }
  }
];

const retorno = $input.first().json;
const contas = retorno.results ?? [];

if (contas.length === 0) {
  throw new Error(
    "A Pluggy não retornou nenhuma conta bancária."
  );
}

// Procura primeiro uma conta corrente
let contaExtrato = contas.find(conta =>
  conta.type === "BANK" &&
  conta.subtype === "CHECKING_ACCOUNT"
);

// Se a instituição não classificar como conta corrente,
// utiliza a primeira conta do tipo BANK.
if (!contaExtrato) {
  contaExtrato = contas.find(conta =>
    conta.type === "BANK"
  );
}

if (!contaExtrato) {
  throw new Error(
    "Nenhuma conta disponível para consultar o extrato."
  );
}

return [
  {
    json: {
      item_id: contaExtrato.itemId,
      account_id: contaExtrato.id,

      banco: contaExtrato.name,
      tipo: contaExtrato.type,
      subtipo: contaExtrato.subtype,

      numero: contaExtrato.number,
      titular: contaExtrato.owner,
      documento: contaExtrato.taxNumber,
      saldo: contaExtrato.balance,

      transfer_number:
        contaExtrato.bankData?.transferNumber ?? null
    }
  }
];

 // Recebe a resposta do HTTP Request da Pluggy
const entradas = $input.all().map(item => item.json);

// A Pluggy pode devolver:
// 1. { results: [...] }
// 2. diretamente vários investimentos
let investimentosOriginais = [];

for (const entrada of entradas) {
  if (Array.isArray(entrada.results)) {
    investimentosOriginais.push(...entrada.results);
  } else if (entrada.id && entrada.itemId) {
    investimentosOriginais.push(entrada);
  }
}

if (investimentosOriginais.length === 0) {
  throw new Error(
    "A Pluggy não retornou nenhum investimento."
  );
}

function numero(valor) {
  if (
    valor === null ||
    valor === undefined ||
    valor === ""
  ) {
    return null;
  }

  const convertido = Number(valor);

  return Number.isFinite(convertido)
    ? convertido
    : null;
}

function arredondar(valor) {
  return Math.round(
    (Number(valor || 0) + Number.EPSILON) * 100
  ) / 100;
}

// Mantém somente investimentos ativos.
// TOTAL_WITHDRAWAL representa investimento totalmente resgatado.
const investimentosAtivos = investimentosOriginais.filter(
  investimento =>
    String(investimento.status || "").toUpperCase() === "ACTIVE"
);

const investimentos = investimentosAtivos.map(
  investimento => ({
    investimento_id: investimento.id,
    item_id: investimento.itemId,

    nome: investimento.name || null,
    numero: investimento.number || null,
    codigo: investimento.code || null,
    isin: investimento.isin || null,

    tipo: investimento.type || null,
    subtipo: investimento.subtype || null,
    status: investimento.status || null,

    moeda: investimento.currencyCode || "BRL",
    titular: investimento.owner || null,

    saldo_atual: numero(investimento.balance),
    valor_unitario: numero(investimento.value),
    quantidade: numero(investimento.quantity),
    valor_bruto: numero(investimento.amount),
    valor_original: numero(investimento.amountOriginal),
    valor_resgate: numero(investimento.amountWithdrawal),
    lucro: numero(investimento.amountProfit),

    impostos: numero(investimento.taxes),
    outros_impostos: numero(investimento.taxes2),

    rentabilidade_mes:
      numero(investimento.lastMonthRate),

    rentabilidade_12_meses:
      numero(investimento.lastTwelveMonthsRate),

    rentabilidade_anual:
      numero(investimento.annualRate),

    taxa: numero(investimento.rate),
    tipo_taxa: investimento.rateType || null,
    periodicidade_taxa:
      investimento.ratePeriodicity || null,

    taxa_fixa_anual:
      numero(investimento.fixedAnnualRate),

    informacao_indexador:
      investimento.indexerAdditionalInfo || null,

    isento_imposto:
      investimento.taxExempt ?? null,

    emissor: investimento.issuer || null,
    emissor_cnpj: investimento.issuerCNPJ || null,

    instituicao:
      investimento.institution?.name || null,

    instituicao_documento:
      investimento.institution?.number || null,

    data_posicao: investimento.date || null,
    data_compra: investimento.purchaseDate || null,
    data_emissao: investimento.issueDate || null,
    data_vencimento: investimento.dueDate || null,
    data_carencia:
      investimento.gracePeriodDate || null,

    regime_tributario:
      investimento.metadata?.taxRegime || null,

    numero_proposta:
      investimento.metadata?.proposalNumber || null,

    numero_processo:
      investimento.metadata?.processNumber || null,

    atualizado_em: investimento.updatedAt || null
  })
);

// Totais da carteira ativa
const saldoTotal = investimentos.reduce(
  (total, investimento) =>
    total + Number(investimento.saldo_atual || 0),
  0
);

const valorOriginalTotal = investimentos.reduce(
  (total, investimento) =>
    total + Number(investimento.valor_original || 0),
  0
);

const lucroTotal = investimentos.reduce(
  (total, investimento) =>
    total + Number(investimento.lucro || 0),
  0
);

const impostosTotal = investimentos.reduce(
  (total, investimento) =>
    total +
    Number(investimento.impostos || 0) +
    Number(investimento.outros_impostos || 0),
  0
);

// Agrupa o saldo por tipo
const porTipo = {};

for (const investimento of investimentos) {
  const tipo = investimento.tipo || "OUTROS";

  if (!porTipo[tipo]) {
    porTipo[tipo] = {
      tipo,
      quantidade: 0,
      saldo: 0
    };
  }

  porTipo[tipo].quantidade += 1;
  porTipo[tipo].saldo += Number(
    investimento.saldo_atual || 0
  );
}

const distribuicao = Object.values(porTipo).map(
  grupo => ({
    ...grupo,
    saldo: arredondar(grupo.saldo)
  })
);

return [
  {
    json: {
      ok: true,

      item_id:
        investimentosOriginais[0]?.itemId || null,

      resumo: {
        quantidade_recebida:
          investimentosOriginais.length,

        quantidade_ativa:
          investimentos.length,

        quantidade_encerrada:
          investimentosOriginais.length -
          investimentos.length,

        saldo_total:
          arredondar(saldoTotal),

        valor_original_total:
          arredondar(valorOriginalTotal),

        lucro_total:
          arredondar(lucroTotal),

        impostos_total:
          arredondar(impostosTotal)
      },

      distribuicao,

      investimentos
    }
  }
];

 const contas = $json.results || [];

return contas
  .filter(conta =>
    conta.type === "CREDIT" &&
    conta.subtype === "CREDIT_CARD"
  )
  .map(cartao => ({
    json: cartao
  }));
